import * as THREE from './three.js';
import {cars,maps} from './catalog.js';
import {createTrack} from './track.js';
import {makeCar,animateCar} from './car-models.js';
import {buildWorld,disposeWorld} from './world.js';
import {createWeather,weatherPresets} from './weather.js';
import {makeSimulation,stepSimulation,standings,profiles,resetToRoad} from './simulation.js';
import {updateDamage} from './damage.js';
import {createLanClient} from './lan-client.js';
const $=id=>document.getElementById(id);
let selectedCar=0,selectedMap=0,selectedWeather='clear',mode='garage',sim,player,world,weather,keys={},last=0,soundOn=false,audio,osc,gain,finishedShown=false,autopilot=false,lanActive=false,netClock=0,hudClock=0;
let track=createTrack(maps[0]);const models=new Map();
const scene=new THREE.Scene();scene.background=new THREE.Color(0x101b32);scene.fog=new THREE.FogExp2(0x101b32,.001);
let renderer;try{renderer=new THREE.WebGLRenderer({canvas:$('world'),antialias:true,powerPreference:'high-performance'});}catch(e){$('error').hidden=false;throw e;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;
const camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,.2,1600);scene.add(new THREE.HemisphereLight(0x91b7e8,0x283537,1.3));const moon=new THREE.DirectionalLight(0xb1caff,1.15);moon.position.set(-140,250,-160);scene.add(moon);const garageLight=new THREE.PointLight(0xc2e7ff,85,35,1.4);scene.add(garageLight);
function disposeModel(model){scene.remove(model);model.traverse(o=>{o.geometry?.dispose();for(const m of o.material?(Array.isArray(o.material)?o.material:[o.material]):[])m.dispose();});}
function syncModels(){for(const [id,model] of models)if(!sim.drivers.some(d=>d.id===id&&d.spec.id===model.userData.spec.id)){disposeModel(model);models.delete(id);}for(const d of sim.drivers){if(!models.has(d.id)){const model=makeCar(d.spec);model.position.set(d.state.x,.15,d.state.z);model.rotation.y=d.state.heading;scene.add(model);models.set(d.id,model);}d.car=models.get(d.id);}}
function environment(){if(world){scene.remove(world.root);disposeWorld(world);}weather?.dispose();track=sim.track;world=buildWorld(track);scene.add(world.root);weather=createWeather(scene,sim.weather);if(world.roadSurface){world.roadSurface.material.roughness=['rain','storm'].includes(sim.weather.id)?.22:.86;world.roadSurface.material.metalness=['rain','storm'].includes(sim.weather.id)?.45:0;if(sim.weather.id==='snow')world.roadSurface.material.color.set(0x717d89);}}
function preview(){sim=makeSimulation({map:selectedMap,car:selectedCar,weather:selectedWeather});player=sim.drivers[0];environment();syncModels();garageLight.visible=true;renderGarage();}
function selectCar(i){selectedCar=i;preview();}function selectMap(i){selectedMap=i;preview();}
function miniCar(s){const shapes={muscle:'M7 38L12 29L42 27L55 14L82 14L99 27L119 31L124 39Z',hyper:'M7 38Q13 26 41 26Q51 12 75 15L98 26Q118 28 123 38Z',f40:'M5 38L9 27L48 23L59 13L81 13L95 24L115 24L115 12L123 12L123 38Z',wedge:'M4 38L22 29L49 23L62 12L83 12L98 24L119 27L124 38Z',porsche:'M7 38Q9 25 31 25Q46 8 69 13Q83 17 91 28Q114 23 121 38Z',skyline:'M8 38L8 25L41 25L51 12L82 12L95 25L113 25L113 15L120 15L120 38Z',bmw:'M8 38L11 26L39 26L51 12L84 12L97 26L121 29L124 38Z',rx7:'M7 38Q10 28 39 26Q54 10 77 14L94 27Q112 27 121 38Z'};return '<svg viewBox="0 0 130 50" aria-hidden="true"><path d="'+shapes[s.style]+'" fill="#'+s.color.toString(16)+'"/><path d="M49 26L59 16H78L89 26Z" fill="#1b3046"/><circle cx="30" cy="39" r="8" fill="#0c1726" stroke="#b4c7d2" stroke-width="2"/><circle cx="100" cy="39" r="8" fill="#0c1726" stroke="#b4c7d2" stroke-width="2"/></svg>';}
function miniMap(def){const xs=def.points.map(p=>p[0]),zs=def.points.map(p=>p[1]),minX=Math.min(...xs),minZ=Math.min(...zs),rx=Math.max(...xs)-minX,rz=Math.max(...zs)-minZ;return '<svg viewBox="0 0 92 66" aria-hidden="true"><polygon points="'+def.points.map(([x,z])=>(6+(x-minX)/rx*80)+','+(5+(z-minZ)/rz*55)).join(' ')+'" fill="none" stroke="#'+def.color.toString(16)+'" stroke-width="3" stroke-linejoin="round"/></svg>';}
function renderGarage(){
 $('cars').innerHTML=cars.map((s,i)=>'<button class="car '+(i===selectedCar?'active':'')+'" data-car="'+i+'" aria-pressed="'+(i===selectedCar)+'">'+miniCar(s)+'<strong>'+s.name+'</strong><small>'+s.era+'</small></button>').join('');
 $('maps').innerHTML=maps.map((m,i)=>'<button class="mapchoice '+(i===selectedMap?'active':'')+'" data-map="'+i+'" aria-pressed="'+(i===selectedMap)+'">'+miniMap(m)+'<strong>'+m.name+'</strong><small>'+m.tag+'</small></button>').join('');
 $('cardetail').innerHTML='<strong>'+cars[selectedCar].name+'</strong><p>'+cars[selectedCar].description+'</p><div class="stats"><span>SPEED <b>'+Math.round(cars[selectedCar].max*.93*3.6)+'</b></span><span>GRIP <b>'+Math.round(cars[selectedCar].grip*80)+'</b></span><span>MASS <b>'+cars[selectedCar].mass+' KG</b></span></div>';
 $('mapdetail').textContent=maps[selectedMap].description;$('location').textContent=maps[selectedMap].name.toUpperCase();$('racelocation').textContent=maps[selectedMap].name.toUpperCase()+' / '+selectedWeather.toUpperCase();
 $('weatherchoices').innerHTML=weatherPresets.map(w=>'<button data-weather="'+w.id+'" class="'+(selectedWeather===w.id?'active':'')+'" aria-pressed="'+(selectedWeather===w.id)+'">'+w.name+'</button>').join('');
 document.querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>selectCar(+b.dataset.car));document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>selectMap(+b.dataset.map));document.querySelectorAll('[data-weather]').forEach(b=>b.onclick=()=>{selectedWeather=b.dataset.weather;preview();});}
const smokePool=Array.from({length:80},()=>{const m=new THREE.Mesh(new THREE.IcosahedronGeometry(.5,0),new THREE.MeshBasicMaterial({color:0x9bb3c4,transparent:true,opacity:0,depthWrite:false}));m.visible=false;m.userData.life=0;scene.add(m);return m;});let effectClock=0,smokeIndex=0;
function effects(dt){for(const p of smokePool){if(p.userData.life<=0)continue;p.userData.life-=dt;p.visible=p.userData.life>0;p.position.y+=dt*.5;p.scale.addScalar(dt*.8);p.material.opacity=Math.max(0,p.userData.life*.17);}effectClock+=dt;if(effectClock<.055)return;effectClock=0;for(const d of sim.drivers){if(!d.state.drifting&&!d.state.offroad)continue;if(d.state.speed<10)continue;for(const x of [-d.spec.width/2,d.spec.width/2]){const rear=new THREE.Vector3(x,.3,-d.spec.length*.35).applyQuaternion(d.car.quaternion).add(d.car.position),p=smokePool[smokeIndex++%smokePool.length];p.position.copy(rear);p.scale.setScalar(.5);p.visible=true;p.userData.life=1.1;}}}
function startRace(){if(lanActive){lan.start().catch(e=>$('lanstatus').textContent=e.message);return;}sim=makeSimulation({map:selectedMap,car:selectedCar,weather:selectedWeather});player=sim.drivers[0];syncModels();enterRace();}
function enterRace(){mode='race';finishedShown=false;keys={};garageLight.visible=false;$('garage').hidden=true;$('hud').hidden=false;$('overlay').hidden=true;$('lanoverlay').hidden=true;$('touch').hidden=!matchMedia('(pointer:coarse)').matches;updateHUD();}
async function garage(){if(lanActive){await lan.leave();lanActive=false;}mode='garage';keys={};$('garage').hidden=false;$('hud').hidden=true;$('overlay').hidden=true;$('touch').hidden=true;$('lanoverlay').hidden=true;preview();}
function pause(){if(mode!=='race')return;if(lanActive){if(lan.session.id!==lan.session.host){$('netnotice').textContent='Only the room host can pause all racers.';return;}lan.pause(!sim.paused).catch(e=>$('netnotice').textContent=e.message);return;}sim.paused=!sim.paused;showPause();}
function showPause(){keys={};$('overlay').hidden=!sim.paused;if(!sim.paused)return;$('resume').hidden=false;$('modaleyebrow').textContent='TAKE A BREATHER';$('modaltitle').textContent='PAUSED.';$('modaltext').textContent='The streets can wait.';$('results').innerHTML='';}
function fmt(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0')+'.'+String(Math.floor(t%1*100)).padStart(2,'0');}
const mapctx=$('map').getContext('2d');function drawMap(){mapctx.clearRect(0,0,180,140);mapctx.strokeStyle='#b4c9db80';mapctx.lineWidth=3;const ext=track.points.reduce((e,p)=>({x:Math.max(e.x,Math.abs(p.x)),z:Math.max(e.z,Math.abs(p.z))}),{x:1,z:1}),scale=Math.min(78/ext.x,58/ext.z);mapctx.beginPath();for(let i=0;i<=200;i++){const p=track.sample(i/200*track.length).p;i?mapctx.lineTo(90+p.x*scale,70+p.z*scale):mapctx.moveTo(90+p.x*scale,70+p.z*scale);}mapctx.stroke();for(const d of sim.drivers){mapctx.fillStyle=d===player?'#e5f58c':d.human?'#ed95da':d.state.boosting?'#7dddff':'#d9e1db';mapctx.beginPath();mapctx.arc(90+d.state.x*scale,70+d.state.z*scale,d===player?4:2.6,0,7);mapctx.fill();}}
function updateHUD(){if(!player)return;const s=player.state,rank=standings(sim);$('position').textContent=rank.indexOf(player)+1;$('lap').textContent=Math.min(3,Math.floor(player.checkpoint/32)+1)+' / 3';$('timer').textContent=fmt(sim.elapsed);$('speed').textContent=String(Math.round(s.speed*3.6)).padStart(3,'0');$('nitro').style.width=s.nitro+'%';$('driftlabel').textContent=s.offroad?'OFF ROAD / R TO RECOVER':s.nitroLocked?(keys.shift?'EMPTY / RELEASE SHIFT':'NITRO RECHARGING'):s.handbraking?'HANDBRAKE':s.drifting?'DRIFT / COUNTERSTEER':s.boosting?'NITRO ENGAGED':'SHIFT / NITRO';
 $('standings').innerHTML=rank.map((r,i)=>'<div class="standing '+(r===player?'you':'')+'"><span>'+(i+1)+'</span><b>'+escapeText(r.name)+'</b><em>'+(r.state.boosting?'N₂O ⚡':r===player?'YOU':r.human?'LAN':r.profile?.skill||r.skill)+'</em></div>').join('');const damage=s.damage;$('damage').textContent='DAMAGE  F '+Math.round(damage.front*100)+'%  R '+Math.round(damage.rear*100)+'%  L '+Math.round(damage.left*100)+'%  R '+Math.round(damage.right*100)+'%';$('laptime').textContent=player.lapTimes.length?'LAST '+fmt(player.lapTimes.at(-1))+' / BEST '+fmt(Math.min(...player.lapTimes)):'BEST LAP —';$('autopilot').textContent=autopilot?'AUTOPILOT ON [P]':'AUTOPILOT OFF [P]';$('autopilot').classList.toggle('active',autopilot);drawMap();}
function escapeText(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function showFinished(){finishedShown=true;mode='finished';keys={};const rank=standings(sim),position=rank.indexOf(player)+1;$('overlay').hidden=false;$('touch').hidden=true;$('resume').hidden=true;$('modaleyebrow').textContent=position===1?'STREET RUN / VICTORY':'STREET RUN / COMPLETE';$('modaltitle').textContent=position===1?'NIGHT IS YOURS.':'P'+position+'. NICE RUN.';$('modaltext').textContent=maps[selectedMap].name+' · '+player.spec.name+' · '+fmt(player.finished||sim.elapsed);$('results').innerHTML=player.lapTimes.map((t,i)=>'<div class="standing"><span>LAP '+(i+1)+'</span><b>'+fmt(t)+'</b></div>').join('');updateHUD();}
function input(){return {steer:(keys.arrowright||keys.d?1:0)-(keys.arrowleft||keys.a?1:0),gas:keys.arrowup||keys.w,brake:keys.arrowdown||keys.s,handbrake:keys[' '],nitro:keys.shift,recover:keys.r,autopilot};}
function renderCars(dt){for(const d of sim.drivers){const s=d.state;if(lanActive&&mode!=='garage'){d.car.position.x=THREE.MathUtils.lerp(d.car.position.x,s.x,1-Math.exp(-dt*22));d.car.position.z=THREE.MathUtils.lerp(d.car.position.z,s.z,1-Math.exp(-dt*22));const delta=Math.atan2(Math.sin(s.heading-d.car.rotation.y),Math.cos(s.heading-d.car.rotation.y));d.car.rotation.y+=delta*(1-Math.exp(-dt*22));}else{d.car.position.set(s.x,.15,s.z);d.car.rotation.y=s.heading;}animateCar(d.car,s,dt);updateDamage(d.car,s);}}
const camPos=new THREE.Vector3(),look=new THREE.Vector3();function updateCamera(dt){const s=player.state,v=new THREE.Vector3(Math.sin(s.heading),0,Math.cos(s.heading)),right=new THREE.Vector3(-v.z,0,v.x);if(mode==='garage'){camera.position.copy(player.car.position).addScaledVector(v,10).addScaledVector(right,11);camera.position.y=4.5;look.copy(player.car.position).addScaledVector(right,3);look.y=1;camera.lookAt(look);garageLight.position.copy(player.car.position).add(new THREE.Vector3(0,7,3));}else{camPos.copy(player.car.position).addScaledVector(v,-(s.boosting?12:10));camPos.y=5;camera.position.lerp(camPos,1-Math.exp(-dt*5));look.copy(player.car.position).addScaledVector(v,16);look.y=1.2;camera.lookAt(look);}camera.fov=THREE.MathUtils.lerp(camera.fov,s.boosting?69:58,dt*3);camera.updateProjectionMatrix();}
function initAudio(){if(!audio){audio=new AudioContext();osc=audio.createOscillator();gain=audio.createGain();osc.type='sawtooth';osc.connect(gain);gain.connect(audio.destination);gain.gain.value=0;osc.start();}audio.resume();}
const lan=createLanClient((packet,session)=>{session.host=packet.host;$('lanroom').textContent='ROOM '+packet.room;$('lanplayers').innerHTML=packet.players.map(p=>'<div class="standing"><b>'+escapeText(p.name)+'</b><em>'+cars[p.car].name+'</em></div>').join('');$('lanstart').hidden=session.id!==packet.host;$('lanstatus').textContent=session.id===packet.host?'Share the address and room code. Start when everyone is here.':'Waiting for the host to start.';if(!packet.state)return;const data=packet.state,changed=selectedMap!==data.map||selectedWeather!==data.weather;selectedMap=data.map;selectedWeather=data.weather;const wasPaused=sim?.paused;sim={...data,track:changed?createTrack(maps[data.map]):track,weather:weatherPresets.find(w=>w.id===data.weather),drivers:data.drivers.map(d=>({...d,spec:cars[d.car]}))};track=sim.track;player=sim.drivers.find(d=>d.id===session.id)||sim.drivers[0];syncModels();if(changed)environment();if(mode==='garage'||(finishedShown&&data.mode==='race'))enterRace();if(wasPaused!==sim.paused)showPause();if(player.finished!=null&&!finishedShown)showFinished();},message=>{$('lanstatus').textContent=message;$('netnotice').textContent=message;});
async function openLan(){const available=await lan.detect();$('lanoverlay').hidden=false;$('lanavailable').hidden=!available;$('languide').hidden=available;$('lanstatus').textContent='';}
$('lanbutton').onclick=openLan;$('lanclose').onclick=()=>{$('lanoverlay').hidden=true;};$('lancreate').onclick=async()=>{try{await lan.create({name:$('lanname').value||'HOST',car:selectedCar,map:selectedMap,weather:selectedWeather});lanActive=true;$('lanconnect').hidden=true;}catch(e){$('lanstatus').textContent=e.message;}};$('lanjoin').onclick=async()=>{try{await lan.join({name:$('lanname').value||'DRIVER',car:selectedCar,room:$('lancode').value});lanActive=true;$('lanconnect').hidden=true;}catch(e){$('lanstatus').textContent=e.message;}};$('lanstart').onclick=()=>lan.start().catch(e=>$('lanstatus').textContent=e.message);$('lanleave').onclick=async()=>{await lan.leave();lanActive=false;$('lanconnect').hidden=false;$('lanplayers').innerHTML='';$('lanroom').textContent='LAN MULTIPLAYER';$('lanstart').hidden=true;};
$('start').onclick=startRace;$('restart').onclick=startRace;$('garagebtn').onclick=garage;$('pause').onclick=pause;$('resume').onclick=pause;$('home').onclick=e=>{e.preventDefault();garage();};$('autopilot').onclick=()=>autopilot=!autopilot;$('recover').onclick=()=>{if(lanActive){keys.r=true;setTimeout(()=>keys.r=false,150);}else resetToRoad(sim,player);};$('sound').onclick=()=>{soundOn=!soundOn;$('sound').textContent=soundOn?'SOUND ON':'SOUND OFF';if(soundOn)initAudio();};
addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Shift'].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key==='Escape'&&!e.repeat)pause();if(e.key.toLowerCase()==='p'&&!e.repeat)autopilot=!autopilot;if(mode==='garage'&&e.key==='Enter')startRace();});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{keys={};if(mode==='race'&&!lanActive&&!sim.paused)pause();});document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key.toLowerCase()]=true;};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key.toLowerCase()]=false;});
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();preview();
function frame(now){const dt=Math.min((now-last)/1000||.016,.05);last=now;if(mode==='race'&&!lanActive){stepSimulation(sim,dt,{[player.id]:input()});if(player.finished!=null&&!finishedShown)showFinished();}netClock+=dt;if(lanActive&&mode==='race'&&netClock>.04){lan.send(input());netClock=0;}renderCars(dt);world.updateLights(player.d);weather.update(dt,player.state);if(mode==='race'&&!sim.paused)effects(dt);updateCamera(dt);if(mode==='race')$('message').textContent=sim.countdown>.5?Math.ceil(sim.countdown-.5):sim.countdown>0?'GO':'';document.body.classList.toggle('boosting',player.state.boosting);hudClock+=dt;if(hudClock>.1){updateHUD();hudClock=0;}if(gain){gain.gain.setTargetAtTime(soundOn&&mode==='race'&&!sim.paused?.018:0,audio.currentTime,.08);osc.frequency.setTargetAtTime(45+player.state.speed*2.6,audio.currentTime,.05);}renderer.render(scene,camera);requestAnimationFrame(frame);}requestAnimationFrame(frame);
window.racingDiagnostics=()=>({mode,paused:sim.paused,lap:Math.floor(player.checkpoint/32)+1,distance:player.d,...player.state,elapsed:sim.elapsed,selectedCar:player.spec.id,selectedMap:maps[selectedMap].id,weather:selectedWeather,trackLength:track.length,contacts:sim.contacts,autopilot,lan:lanActive,props:world.layout.props.length,rivals:sim.drivers.filter(d=>d!==player).map(d=>({name:d.name,car:d.spec.id,distance:d.d,checkpoint:d.checkpoint,nitro:d.state.nitro,nitroSeconds:d.nitroSeconds,finished:d.finished})),lapTimes:player.lapTimes,freeDriving:true,night:true});
